            invFactorial[i] = (invFactorial[i - 1] * modInverse(i, MOD)) % MOD;
        }
    }

    static long nCr(int n, int r) {
        long res = factorial[n] * invFactorial[r] % MOD;
        res = res * invFactorial[n - r] % MOD;
        return res;
    }

    static long fastPower(long base, long exp) {
        long result = 1;
        long b = base % MOD;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) result = (result * b) % MOD;
            b = (b * b) % MOD;
            e >>= 1;
        }
        return result;
    }

    static void solve() {
        precompute();
        int n = s.nextInt();
        long k = s.nextLong();
