        out.close();
    }

    static class Triplet {
        long gcd, x, y;
        Triplet(long gcd, long x, long y) {
            this.gcd = gcd; this.x = x; this.y = y;
        }
    }

    static Triplet extendedEuclidean(long a, long b) {
        if (a == 0) return new Triplet(b, 0, 1);
        Triplet res = extendedEuclidean(b % a, a);
        long x = res.y - (b / a) * res.x;
        long y = res.x;
        return new Triplet(res.gcd, x, y);
    }

    static long modInverse(long a, long m) {
        Triplet res = extendedEuclidean(a, m);
        if (res.gcd != 1) return -1;
        return (res.x % m + m) % m;
