MOD = 998244353
MAX = int(4e5) + 10
factorial = [1] * MAX
invFactorial = [1] * MAX

def precompute():
    for i in range(2, MAX):
        factorial[i] = (factorial[i - 1] * i) % MOD
        invFactorial[i] = (invFactorial[i - 1] * modInverse(i, MOD)) % MOD

def nCr(n, r):
    res = factorial[n] * invFactorial[r] % MOD
    res = res * invFactorial[n - r] % MOD
    return res

def fastPower(base, exp):
    result = 1
    b = base % MOD
    e = exp
    while e > 0:
        if e & 1:
            result = (result * b) % MOD
        b = (b * b) % MOD
        e >>= 1
    return result

def solve():
    precompute()
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    k = int(input_data[1])
    if k == 0:
        print(factorial[n])
        return
    if n <= k:
        print(0)
        return
    ans = nCr(n, k)
    cols = n - k
    sum_ = 0
    for i in range(cols + 1):
        temp = nCr(cols, i)
        temp = (temp * fastPower(cols - i, n)) % MOD
        if i & 1:
            sum_ -= temp
            if sum_ < 0:
                sum_ += MOD
        else:
            sum_ += temp
            if sum_ >= MOD:
                sum_ -= MOD
    print((2 * ((ans * sum_) % MOD)) % MOD)

def extendedEuclidean(a, b):
    if a == 0:
        return (b, 0, 1)
    gcd, x1, y1 = extendedEuclidean(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return (gcd, x, y)

def modInverse(a, m):
    gcd, x, y = extendedEuclidean(a, m)
    if gcd != 1:
        return -1
    return (x % m + m) % m

if __name__ == "__main__":
    solve()

